const {chromium}=require('playwright'),fs=require('fs'),path=require('path'),assert=require('assert');
(async()=>{const out=process.env.LESSON_OUTPUT_DIR;fs.mkdirSync(out,{recursive:true});const b=await chromium.launch({headless:true,executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH});try{const p=await b.newPage();await p.goto(process.env.LESSON_URL);const html=await p.locator('#handLeft').evaluate(e=>e.outerHTML);const fixture=await b.newPage();await fixture.setContent(html);const records=[];for(const [name,page] of [['lesson',p],['plain-native-no-handlers',fixture]]){await page.selectOption('#handLeft','4');await page.locator('#handLeft').focus();const steps=[];for(const key of [null,'Home','ArrowDown','Enter']){if(key)await page.keyboard.press(key);steps.push({key:key||'focused',...await page.locator('#handLeft').evaluate(e=>({value:e.value,focused:document.activeElement===e}))});}records.push({name,steps});await page.locator('#handLeft').screenshot({path:path.join(out,name+'.png')});assert(steps.every(s=>s.focused));}const result={host:process.platform,browser:b.version(),expectedByOriginalLinuxTest:'3',records};fs.writeFileSync(path.join(out,'native-keyboard-results.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));}finally{await b.close();}})().catch(e=>{console.error(e);process.exitCode=1});
